observableLabel[key_] := Lookup[observableLabels,key,"\\text{"<>key<>"}"];
observableTitle[key_] := Lookup[observableTitles,key,"\\text{"<>key<>"}"];

recordPlot[records_,keys_List,ylabel_,title_,p_,log_:False] := Module[{curves,styles,g},
 curves=Table[Select[({#["Time"],#[key]}& /@ records),NumericQ[Last[#]] && (!log || First[#]>0)&],{key,keys}];
 If[AllTrue[curves,#==={}&],Return[Column[{tex[title,20],tex["\\text{No valid samples under the selected tolerances.}",14]}]]];
 styles=Table[Directive[ColorData[97][k],AbsoluteThickness[2]],{k,Length[keys]}];
 g=Block[{plotChop=0},framePlot[curves,"t",ylabel,styles,
  (observableLabel /@ keys),False,log,Table[{"\[FilledCircle]",3},{Length[keys]}]]];
 plotPanel[title,trajectoryCaption[p,records],g]
];
statePlots[records_,p_,log_:False] := Module[{out=<||>,scalars,curves,styles,g,fn,pairs=Subsets[Range[4],{2}],basis={"00","01","10","11"}},
 scalars=Select[Keys[First[records]],# != "Time" && NumericQ[First[records][#]]&];
 Do[AssociateTo[out,key->recordPlot[records,{key},observableLabel[key],observableTitle[key],p,log]],{key,scalars}];
 curves=Table[Select[({#["Time"],Re[#["RhoAB"][[k,k]]]}& /@ records),!log || First[#]>0&],{k,4}];
 g=Block[{plotChop=0},framePlot[curves,"t","\\rho_{AB;ss}",curveStyles[4],("\\rho_{"<>#<>","<>#<>"}(t)"& /@ basis),False,log,Table[{"\[FilledCircle]",3},{4}]]];
 AssociateTo[out,"EdgePopulations"->plotPanel["\\text{Edge populations}",trajectoryCaption[p,records],g]];
 Do[fn=Switch[part,"Re",Re,"Im",Im,"Abs",Abs];
  curves=Table[Select[({#["Time"],fn[#["RhoAB"][[pair[[1]],pair[[2]]]]]}& /@ records),!log || First[#]>0&],{pair,pairs}];
  g=Block[{plotChop=0},framePlot[curves,"t","\\operatorname{"<>part<>"}\\rho_{AB;ij}",curveStyles[6],
   (If[part=="Abs","|\\rho_{","\\operatorname{"<>part<>"}\\rho_{"]<>basis[[#[[1]]]]<>","<>basis[[#[[2]]]]<>If[part=="Abs","}|","}"]& /@ pairs),False,log,Table[{"\[FilledCircle]",3},{6}]]];
  AssociateTo[out,"EdgeCoherences_"<>part->plotPanel["\\text{Edge coherences}",trajectoryCaption[p,records],g]];
  curves=Table[Select[({#["Time"],fn[#[key][[1,2]]]}& /@ records),!log || First[#]>0&],{key,{"RhoA","RhoB"}}];
  g=Block[{plotChop=0},framePlot[curves,"t","\\operatorname{"<>part<>"}\\rho_{Q;01}",curveStyles[2],(If[part=="Abs","|\\rho_{","\\operatorname{"<>part<>"}\\rho_{"]<>#<>";01}"<>If[part=="Abs","|",""]& /@ {"A","B"}),False,log,Table[{"\[FilledCircle]",3},{2}]]];
  AssociateTo[out,"LocalCoherences_"<>part->plotPanel["\\text{Single-edge coherences}",trajectoryCaption[p,records],g]],{part,{"Re","Im","Abs"}}];
 curves=Table[Select[({#["Time"],#["EigenvaluesAB"][[k]]}& /@ records),!log || First[#]>0&],{k,4}];
 g=Block[{plotChop=0},framePlot[curves,"t","\\lambda_k(\\rho_{AB})",curveStyles[4],Table["\\lambda_"<>ToString[k]<>"(\\rho_{AB})",{k,4}],False,log,Table[{"\[FilledCircle]",3},{4}]]];
 AssociateTo[out,"EdgeDensityEigenvalues"->plotPanel["\\text{Edge density spectrum}",trajectoryCaption[p,records],g]];out
];


mapPlots[records_,p_,log_:False] := Module[{out=<||>,keys,aug,names},
 keys={"MinChoiEigenvalue","TPError","ChoiTraceError","KrausRank","MapEntropy","ChoiPTMinimum","ChoiNegativity",
  "MinSingularValue","MinimumRate","RHPInstantaneous","RHPFiniteStep","RHPFiniteStepRate",
  "UnitalityError","MixedInputEntropy","U1CovarianceError","ReflectionCovarianceError","FlipCovarianceError","RFCovarianceError",
  "DoubleQuantumReal","DoubleQuantumImag","DoubleQuantumAbs","BLPDistance","BLPAccumulated","SignalAtoB","RetentionA"};
 Do[AssociateTo[out,key->recordPlot[records,{key},observableLabel[key],observableTitle[key],p,log]],{key,keys}];
 Do[names=Table[spec[[1]]<>ToString[k],{k,spec[[2]]}];
  aug=Map[Function[r,Join[r,Association[MapThread[Rule,{names,r[spec[[1]]]}]]]],records];
  AssociateTo[out,spec[[1]]->recordPlot[aug,names,spec[[3]],spec[[4]],p,log]],
  {spec,{{"ChoiEigenvalues",16,"\\lambda_k(C_t)","\\text{Choi eigenvalues}"},{"CanonicalRates",15,"\\gamma_k(t)","\\text{Canonical rates}"}}}];out
];


(* ::Text:: *)
(*  Strict MaTeX: fail clearly instead of exporting unrendered TeX strings.  *)


(* ::Input:: *)


tex[s_String,size_:16] := Module[{g},
 If[!TrueQ[texReady],check[Quiet[Check[Needs["MaTeX`"];True,False]],"Install/configure MaTeX before making plots."];texReady=True];
 g=Quiet[Check[MaTeX`MaTeX[s,FontSize->size],$Failed]];
 check[MatchQ[g,_Graphics],"MaTeX could not render: "<>s];g
];
texReady=False;
trajectoryCaption[snap_,records_] := regimeCaption[snap["Model"],
 "\\text{bulk: "<>Lookup[snap,"BulkChoice","chosen ket"]<>"};\\quad "<>
 samplingCaption[Lookup[records,"Time"],Lookup[snap,"TimeSettings",<||>]]];
regimeCaption[p_,extra_:""] := Column[tex[#,13]& /@ DeleteCases[{
 "\\mathrm{"<>p["Regime"]<>"}:\\quad N="<>texNumber[p["N"]]<>";\\quad L="<>texNumber[p["L"]]<>
 ";\\quad J="<>texNumber[p["J"]]<>";\\quad g="<>texNumber[p["g"]]<>";\\quad \\Delta="<>texNumber[p["Delta"]],
 "\\gamma="<>texNumber[p["Gamma"]]<>";\\quad \\varphi="<>texNumber[p["Phi"]]<>
 ";\\quad \\Psi_"<>ToString[p["Family"]]<>If[p["Handedness"]==1,"^{+}","^{-}"]<>
 ";\\quad \\mathrm{"<>p["BoundaryBranch"]<>"}",
 "\\mathbf h_1=(J/2,0,0),\\quad \\mathbf h_N=(J\\cos\\varphi/2,J\\sin\\varphi/2,0)",extra},""],Alignment->Center];
AssociateTo[observableLabels,{"EntanglingConcurrence"->"\\max_{\\rho_{AB}\\in\\mathrm{Sep}}\\mathcal C[\\Lambda_t(\\rho_{AB})]",
 "MinDephasingEigenvalue"->"\\lambda_{\\min}(\\Gamma_t)","DephasingPopulationError"->"\\max_a|\\Gamma_{aa}-1|"}];
AssociateTo[observableTitles,{"EntanglingConcurrence"->"\\text{ZZ entanglement generation from product edges}",
 "MinDephasingEigenvalue"->"\\text{Dephasing-matrix positivity}","DephasingPopulationError"->"\\text{Dephasing population check}"}];
gammaPlots[records_,snap_,log_:False] := Module[{pairs=Subsets[Range[4],{2}],basis={"00","01","10","11"},fn,curves,g,out=<||>},
 Do[fn=Switch[part,"Re",Re,"Im",Im,"Abs",Abs];
  curves=Table[Select[({#["Time"],fn[#["DephasingFactors"][[pair[[1]],pair[[2]]]]]}& /@ records),!log || First[#]>0&],{pair,pairs}];
  g=Block[{plotChop=0},framePlot[curves,"t","\\operatorname{"<>part<>"}\\Gamma_{ab}(t)",curveStyles[6],
   ("\\Gamma_{"<>basis[[#[[1]]]]<>","<>basis[[#[[2]]]]<>"}"& /@ pairs),False,log,Table[{"\[FilledCircle]",3},{6}]]];
  AssociateTo[out,"Gamma_"<>part->plotPanel["\\text{Conditional bulk overlaps}",trajectoryCaption[snap,records],g]],{part,{"Re","Im","Abs"}}];out
];
channelPlots[records_,snap_,log_:False] := Module[{out=mapPlots[records,snap,log]},
 If[First[records]["Choi"]==={},Return[out]];
 If[KeyExistsQ[First[records],"DephasingFactors"],out=Join[out,gammaPlots[records,snap,log]];
  Do[AssociateTo[out,key->recordPlot[records,{key},observableLabel[key],observableTitle[key],snap,log]],
   {key,{"EntanglingConcurrence","MinDephasingEigenvalue","DephasingPopulationError"}}]];out
];
resultRoot[] := FileNameJoin[{workflowDirectory,"xxz_phantom_results"}];
newFolder[root_,tag_] := Module[{d,k=1},d=FileNameJoin[{root,tag}];
 While[DirectoryQ[d],k++;d=FileNameJoin[{root,tag<>"_run"<>ToString[k]}]];
 CreateDirectory[d,CreateIntermediateDirectories->True];d];
exportRun[root_,tag_,statePanels_,channelPanels_,run_] := Module[{dir},
 dir=newFolder[root,tag];
 check[StringQ[Export[FileNameJoin[{dir,"results.wxf"}],run,"WXF"]],"Numerical data export failed."];
 check[StringQ[Export[FileNameJoin[{dir,"settings.txt"}],ToString[KeyDrop[run,{"Records","MapRecords","BulkKet"}],InputForm],"Text"]],"Settings export failed."];
 KeyValueMap[savePNG[FileNameJoin[{dir,"State_"<>#1<>".png"}],#2]&,statePanels];
 KeyValueMap[savePNG[FileNameJoin[{dir,"Channel_"<>#1<>".png"}],#2]&,channelPanels];dir
];


(* ::Subsection:: *)
(*  0.8 Independent small-system reference check  *)


(* ::Input:: *)


smallReferenceCheck[eng_,edge_,ts_List,cfg_] := Module[{h,ef,f,ev,errs={},cherrs={},u,exact,w,c,s,t},
 If[eng["L"]>cfg["DirectReferenceMaximumL"],Return[Missing["SizeAboveReferenceLimit"]]];
 h=Normal[fullHamiltonian[eng["Parameters"]]];ef=stateFactor[edge,4,cfg["ValidationTolerance"]];
 f=eng["InputFactor"];ev=evolveInputs[eng,ts];
 Do[t=ts[[k]];u=MatrixExp[-I t h];exact=u . f;
  AppendTo[errs,maxAbs[exact . ef-ev["Factors"][[k]] . ef]];
  (* Independent explicit sum over bulk basis and edge input/output indices. *)
  c=Table[Sum[exact[[edgeIndices[o,eng["L"]-2][[m]],i]] Conjugate[exact[[edgeIndices[oo,eng["L"]-2][[m]],ii]]],
   {m,2^(eng["L"]-2)}],{i,4},{o,4},{ii,4},{oo,4}];c=ArrayReshape[c,{16,16}];
  AppendTo[cherrs,maxAbs[c-channelValue[ev["Factors"][[k]],ev["Derivatives"][[k]],eng]["Choi"]]],{k,Length[ts]}];
 check[Max[Join[errs,cherrs]]<cfg["ValidationTolerance"],"Direct full-space reference check failed."];
 <|"Times"->ts,"MaximumStateFactorError"->Max[errs],"MaximumChoiError"->Max[cherrs],"Passed"->True|>
];


(* ::Section:: *)
(*  0B. Recover the table energies before adding either probe  *)


(* ::Text:: *)
(*  The verification diagonalizes the isolated field-dressed bulk. A degenerate level is checked by projection onto its full eigenspace, not by comparing with one arbitrary ED eigenvector.  *)


(* ::Text:: *)
(*  Verification controls  *)


(* ::Input:: *)


verificationSettings=<|"EDTolerance"->10^-10,"ValidationTolerance"->10^-8,"DenseWorkingMemoryMB"->4096|>;
verifyAllUploadedSizes=True; (* N=4,...,10; both vectors in every supplied file. *)
verifyAllEightTableRows=True;
verificationN=4;verificationGamma=Pi/3;verificationJ=1;


(* ::Text:: *)
(*  Diagonalization and energy verification  *)


(* ::Input:: *)


verificationUploaded=If[TrueQ[verifyAllUploadedSizes],Flatten[verifySuppliedSizes[verificationSettings],1],{}];
If[verificationUploaded=!={},Print[Dataset[verificationUploaded]];
 Print["Uploaded .txt energies equal -4 times the screenshot/benchmark energies at J=1. The Hamiltonian below uses the screenshot/benchmark convention."]];
verificationTable=If[TrueQ[verifyAllEightTableRows],verifyTableBranches[verificationN,verificationGamma,verificationJ,verificationSettings],{}];
If[verificationTable=!={},Print[Dataset[verificationTable]]];


(* ::Title:: *)
(*  1. ZZ coupling: reduced edge state and Choi dynamics  *)


(* ::Text:: *)
(*  The bulk fields and helix parameters are fixed independently of the two probes. The channel is computed from all four edge basis inputs with this one fixed bulk state. Editing EdgeState changes the reduced-state experiment, not the channel.  *)


(* ::Subsection:: *)
(*  1.1 Independent settings  *)


(* ::Input:: *)


zzModel=<|"N"->4,"J"->1,"Gamma"->Pi/3,"Family"->1,"Handedness"->1,
 "BoundaryBranch"->"PMC","g"->1/10|>;
zzBulkChoice="UploadedPhantom";


(* ::Text:: *)
(*  Choices: "UploadedPhantom", "UploadedSpinCurMax" (given N=4,...,10), or "Analytic" (either family/sign/branch and arbitrary real Gamma). Delta is derived from Gamma; do not choose them independently. N is bulk length, so N=10 means L=12 total spins.  *)


(* ::Input:: *)


zzEdgeState=ConstantArray[1/2,4]; (* Separable |+>_A |+>_B. *)


(* ::Text:: *)
(*  Other pure or mixed edge states are accepted. An initially entangled edge state tests its evolution, not generation from a separable preparation.  *)


(* ::Input:: *)


zzTime=<|"Grid"->"Linear","tMax"->400.,"dt"->0.1,"tMinPositive"->0.01,"LogPoints"->201|>;
zzSettings=<|"EDTolerance"->10^-10,"ValidationTolerance"->10^-8,
 "DenseWorkingMemoryMB"->4096,"BatchTimes"->32,"RecordChop"->10^-12,
 "RankTolerance"->10^-10,"MinimumSingularValue"->10^-8,
 "DirectReferenceMaximumL"->6|>;
zzProbes=<|"Rho1"->ketRho[{1,1,1,1}/2],"Rho2"->ketRho[{1,-1,1,-1}/2],
 "RhoB"->ketRho[{0,1}]|>;


(* ::Text:: *)
(*  These probes define only BLP/signalling witnesses, never the channel.  *)


(* ::Input:: *)


zzEnabled=True;
zzMakePlots=True;
zzExportResults=True;
zzLogHorizontalAxis=False; (* Caption and log axis do not change samples. *)
zzOutputRoot=resultRoot[];
zzRunLabel="Phantom_ZZ_N4"; (* Keep short for Windows paths. *)


(* ::Subsection:: *)
(*  1.2 Verify this bulk ket, then construct only occupied invariant blocks  *)


(* ::Input:: *)


If[TrueQ[zzEnabled],
 zzModelUsed=phantomModel[zzModel,"ZZ"];
 zzBulkChoiceUsed=zzBulkChoice;zzSettingsUsed=zzSettings;
 zzBulkKet=chooseBulkKet[zzModelUsed,zzBulkChoiceUsed];
 zzBulkAudit=bulkEigenAudit[zzModelUsed,zzBulkKet,zzSettingsUsed];
 Print[Dataset[{zzBulkAudit}]];
 { zzSetupSeconds,zzEngine}=AbsoluteTiming[buildEngine[zzModelUsed,zzBulkKet,zzSettingsUsed]];
 Print[Dataset[zzEngine["BulkMagnetizationAudit"]["InitialMagnetizationWeights"]]];
 Print[Dataset[zzEngine["Occupation"]]];
 Print["Magnetization is not a conserved block label with transverse fields. All connected magnetization slices are retained."];
];


(* ::Subsection:: *)
(*  1.3 Reduced density matrix and input-independent Choi channel  *)


(* ::Input:: *)


If[TrueQ[zzEnabled],
 zzTimeUsed=zzTime;zzTimes=timeGrid[zzTimeUsed];
 zzEdgeStateUsed=zzEdgeState;zzProbesUsed=zzProbes;
 { zzSeconds,zzRun}=AbsoluteTiming[runDynamics[zzEngine,zzEdgeStateUsed,zzTimes,zzSettingsUsed,zzProbesUsed]];
 zzReference=smallReferenceCheck[zzEngine,zzEdgeStateUsed,{0.,0.137,1.}, zzSettingsUsed];
 zzRun=Join[zzRun,<|"TimeSettings"->zzTimeUsed,"BulkChoice"->zzBulkChoiceUsed,
  "BulkEigenstateAudit"->zzBulkAudit,"DirectReference"->zzReference,
  "SetupSeconds"->zzSetupSeconds,"EvolutionSeconds"->zzSeconds,
  "UploadedSizeVerification"->verificationUploaded,"TableVerification"->verificationTable|>];
 zzRecords=zzRun["Records"];zzMapRecords=zzRun["MapRecords"];
 zzPlotSnapshot=<|"Model"->zzRun["Model"],"TimeSettings"->zzRun["TimeSettings"],"Times"->zzRun["Times"],"BulkChoice"->zzRun["BulkChoice"]|>;
 Print[Dataset[{zzRun["Checks"]}]];
 Print[Dataset[zzRun["StateMagnetizationAudit"]["InitialMagnetizationWeights"]]];
 Print[Dataset[zzRun["FixedEdgeOccupation"]]];
];


(* ::Text:: *)
(*  Raw data access, with k a time index: zzRecords[[k]]["RhoAB"] : reduced edge state, trace 1. zzMapRecords[[k]]["Choi"] : unnormalized Choi, trace 4. zzMapRecords[[k]]["ChoiState"]: normalized Choi, trace 1. zzMapRecords[[k]]["Transfer"] : row-vectorized map. applyTransfer[zzMapRecords[[k]]["Transfer"],yourEdgeDensityMatrix] For ZZ, "DephasingFactors" is the complete 4x4 Gamma(t).  *)


(* ::Subsection:: *)
(*  1.4 MaTeX figures with the computed-run captions  *)


(* ::Input:: *)


If[TrueQ[zzEnabled],
 zzStatePlots=<||>;zzChannelPlots=<||>;
 If[TrueQ[zzMakePlots],
  zzStatePlots=statePlots[zzRecords,zzPlotSnapshot,zzLogHorizontalAxis];
  zzChannelPlots=channelPlots[zzMapRecords,zzPlotSnapshot,zzLogHorizontalAxis];
  Print[Column[Values[zzStatePlots],Spacings->2]];
  Print[Column[Values[zzChannelPlots],Spacings->2]]];
];


(* ::Subsection:: *)
(*  1.5 Export numerical matrices and figures to the same parent directory  *)


(* ::Input:: *)


If[TrueQ[zzEnabled] && TrueQ[zzExportResults],
 zzDirectory=exportRun[zzOutputRoot,zzRunLabel,zzStatePlots,zzChannelPlots,zzRun];
 Print[zzDirectory];
];


